run_shell "Quality26 release architecture" 'grep -q "tooltip-polish.js" app.js && grep -q "penalty-hardening.js" app.js && grep -q "run-type-stability.js" app.js && grep -q "pick-six.js" app.js && grep -q "live-correction.js" app.js && grep -q "box-ui-v19.js" app.js && grep -q "game-iq-summary.js" app.js && grep -q "quality24.js" app.js && grep -q "tracker-layout-polish.js" app.js && grep -q "box-ux25.js" app.js && grep -q "football-flow26.js" app.js && grep -q "quality26-context-results.js" app.js && ! grep -q "game-day-3.js" app.js && ! grep -q "speed-guard.js" app.js && ! grep -q "game-iq-v3.js" app.js && grep -q "v=quality26" app.js && grep -Eq "app.js\?v=(safety23-final|quality24|quality24-final|quality25|quality25-final|quality26|quality26-final)" index.html && grep -q "football-flow26.css?v=flow26" football-flow26.js && grep -q "quality24.css?v=quality24" quality24.js && grep -q "tracker-layout-polish.css?v=tracker25" tracker-layout-polish.js && grep -q "box-ux25.css?v=boxux25" box-ux25.js && grep -q "box-ui-v19.css?v=box23" box-ui-v19.js && grep -q "visual-polish.css?v=visual23" box-ui-v19.js && grep -q "adaptive-layout.css?v=adaptive23c" box-ui-v19.js && grep -q "pick-six.css?v=pick22" pick-six.js && grep -q "fniq_prod_v1" state.js && grep -q "fniq_recovery_v1" durability.js'
run_shell "Football preset contract" 'grep -q "False Start.*Offense.*Accepted.*5.*REPEAT.*DEAD" penalty-hardening.js && grep -q "Offside.*Defense.*Accepted.*5.*REPEAT.*DEAD" penalty-hardening.js && grep -q "Encroachment.*Defense.*Accepted.*5.*REPEAT.*DEAD" penalty-hardening.js && grep -q "Delay of Game.*Offense.*Accepted.*5.*REPEAT.*DEAD" penalty-hardening.js && grep -q "Holding.*Offense.*Accepted.*10.*COUNT.*LIVE" football-flow26.js'
run_shell "Quality26 booth-football contract" 'grep -q "half the distance" football-flow26.js && grep -q "Official net change" football-flow26.js && grep -q "Cancel Penalty" football-flow26.js && grep -q "Correct situation" football-flow26.js && grep -q "Pre-snap complete" football-flow26.js && grep -q "Fumble Lost" football-flow26.js && grep -q "Inside Zone.*Inside Zone" football-flow26.js && grep -q "Play results" quality26-context-results.js && grep -q "data-q26-tag=\"Penalty\"" qa-browser-football-flow26-release.js && grep -q "live-ball Penalty changed the underlying play type" qa-browser-football-flow26-release.js && grep -q "Permanent dead-ball regression" qa-browser-football-flow26-release.js && grep -q "Half-distance is automatic" qa-browser-football-flow26-release.js && grep -q "Situation correction must update the upcoming snap" qa-browser-football-flow26-release.js && grep -q "critical text too small" qa-browser-football-flow26-release.js'
run_shell "Run Type stability contract" 'grep -q "Inside Zone" run-type-stability.js && grep -q "Outside Zone" run-type-stability.js && grep -q "Counter" run-type-stability.js && grep -q "Power" run-type-stability.js && grep -q "Draw" run-type-stability.js && grep -q "Run Type" run-type-stability.js'
