run_shell "Adaptive viewport and dead-space contract" 'grep -q "width:1475,height:668" qa-browser-responsive.js && grep -q "width:1366,height:768" qa-browser-responsive.js && grep -q "width:1920,height:1080" qa-browser-responsive.js && grep -q "width:2560,height:1440" qa-browser-responsive.js && grep -q "width:390,height:844" qa-browser-responsive.js && grep -q "width:844,height:390" qa-browser-responsive.js && grep -q "width:1366,height:768" qa-browser-tracker-workflow.js && grep -q "width:1660,height:900" qa-browser-tracker-workflow.js && grep -q "DEAD LOWER-RIGHT FAIL" qa-browser-tracker-workflow.js && grep -q "SCROLL FAIL" qa-browser-tracker-workflow.js && grep -q "penalty Save stays reachable" qa-browser-tracker-workflow.js && grep -q "normal run path stays in one viewport" qa-browser-tracker-workflow.js && grep -q "grid-column:1/-1" box-ux25.css && grep -q "grid-auto-rows:max-content" adaptive-layout.css && grep -q "max-height:700px" adaptive-layout.css && grep -q "min-width:1600px" adaptive-layout.css && grep -q "overflow-y:auto" adaptive-layout.css && grep -q "position:static!important" adaptive-layout.css && grep -q "shortSituationEdit" box-ui-v19.js && grep -q "boxHeaderSave" box-ui-v19.js && grep -q "align-items:start" football-flow26.css'
run_shell "Box ergonomics contract" 'grep -q "workstation-1660.*1660.*900" qa-browser-box-ergonomics.js && grep -q "text too small" qa-browser-box-ergonomics.js && grep -q "target too short" qa-browser-box-ergonomics.js && grep -q "dead lower-right area" qa-browser-box-ergonomics.js && grep -q "pre-snap dead internal space" qa-browser-box-ergonomics.js && grep -q "contrast too low" qa-browser-box-ergonomics.js && grep -q "unselected Blitz is visually over-colored" qa-browser-box-ergonomics.js && grep -q "min-height:36px" football-flow26.css && grep -q "font-size:12px" football-flow26.css'
run_shell "Game IQ confidence and data-quality contract" 'grep -q "repeated call with at least 50% success" quality24.js && grep -q "dead-ball looks still count as defensive evidence" quality24.js && grep -q "Charting health" quality24.js && grep -q "Low coverage means lower-confidence Game IQ" quality24.js && grep -q "two-play sample must never become a recommendation" qa-quality24.js && grep -q "repeated unsuccessful call must not become a positive recommendation" qa-quality24.js && grep -q "accepted dead-ball penalty must not enter offensive efficiency" qa-quality24.js && grep -q "charted dead-ball defensive look must remain usable evidence" qa-quality24.js && grep -q "legacy N/A must remain unknown" qa-quality24.js && grep -q "explicit No Motion must count as charted data" qa-quality24.js'
run_shell "Light-mode contract" 'grep -Fq "html[data-theme=\"light\"] #penaltyPanel.boxPenaltyInline" box-ui-v19.css && grep -q "Quick Game Stats values must remain readable in light mode" qa-browser-e2e.js && grep -Fq "html[data-theme=\"light\"] .q24Capture" quality24.css && grep -Fq "html[data-theme=\"light\"].fniqBoxUx25" box-ux25.css && grep -Fq "html[data-theme=\"light\"].fniqFootballFlow26" football-flow26.css'
run_shell "Historical UX contract" 'grep -q "DELAY=3200" tooltip-polish.js && grep -q "Save for quick access" game-iq-polish.js && grep -q "Returned for TD" pick-six.js && grep -q "explosiveRun" analytics.js && grep -q "explosivePass" analytics.js && grep -q "#iq .action.good" visual-polish.css && grep -q "#iq .action.bad" visual-polish.css'
run_shell "No broad observer regression in new layers" '! grep -q "MutationObserver" live-correction.js && ! grep -q "MutationObserver" live-runtime-stability.js && ! grep -q "MutationObserver" box-ui-v19.js && ! grep -q "MutationObserver" penalty-hardening.js && ! grep -q "MutationObserver" run-type-stability.js && ! grep -q "MutationObserver" game-iq-summary.js && ! grep -q "MutationObserver" quality24.js && ! grep -q "MutationObserver" tracker-layout-polish.js && ! grep -q "MutationObserver" box-ux25.js && ! grep -q "MutationObserver" football-flow26.js && ! grep -q "MutationObserver" quality26-context-results.js'
run "Static DOM references" node qa-static-dom.js
run_shell "Code size" 'wc -l *.js *.css index.html | tail -1'
echo "FINAL: PASS" | tee -a "$REPORT"
